#include "stdafx.h"#include "HcdElementBase.h"#include <HcdMemoryService.h>#include <HcdDataTypes_.h>#include <stdio.h>#include <rsuNoNames.h>struct SVariableIn_P{#include "PrivateVars/VariableIn.h"};class KVariableIn : public KHcdElementBase  , protected SVariableIn_P{  CBase *m_pRawBase;  eHcdVType m_prjType;public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void ProjectRestored( SProjRestedParams &params, int N );private:  void DetectType();};static KHcdFactory _VariableIn("VariableIn", KVariableIn::Create);IHcdElement *KVariableIn::Create(){  return new KVariableIn;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KVariableIn, 2 )void KVariableIn::InitParm(){#include "PrivateVars/VariableIn.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KVariableIn::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KVariableIn::DetectType(){  switch( DataType.V )  {  case DataType.Analog:    m_prjType = ehtAnalog32;    break;  case DataType.Digital:    m_prjType = ehtDigital32;    break;  default:    ASSD( 0 );    break;  }}void KVariableIn::ProjectRestored( SProjRestedParams &params, int N ){  if( N < 0 )  {    if( ehtHZ!=m_prjType )      return;    DetectType();    if( ehtAnalog32==m_prjType )    {      m_pRawBase = KMemoryServiceHCD::Instance().CreateSharedObj( szName, W_ANAVAR::TypeID, params.domain );      m_pSharedObject = (BYTE*)m_pRawBase;      m_pSharedVarsInfo = new SVarInfo[2];      AddSharedField( "PV", "OP", offsetof(W_ANAVAR, W_ANAVAR::PV), ehtAnalog32, sizeof(tAnalog32), 2 );      AddSharedField( "OUTR0", NULL, offsetof(W_ANAVAR, W_ANAVAR::PV), ehtAnalog32, sizeof(tAnalog32), 2 );    }    else if( ehtDigital32==m_prjType )    {      m_pRawBase = KMemoryServiceHCD::Instance().CreateSharedObj( szName, W_DIGVAR::TypeID, params.domain );      m_pSharedObject = (BYTE*)m_pRawBase;      m_pSharedVarsInfo = new SVarInfo[2];      AddSharedField( "PV", "OP", offsetof(W_DIGVAR, W_DIGVAR::PV), ehtDigital32, sizeof(tDigital32), 2 );      AddSharedField( "OUTR0", NULL, offsetof(W_DIGVAR, W_DIGVAR::PV), ehtDigital32, sizeof(tDigital32), 2 );    }    else    {      ASS(0);    }    qsort( m_pSharedVarsInfo, m_kSharedVarsInfo, sizeof( SVarInfo ), CompVarInfo );    params.pCtrl->RegisterVar( this );    KNoName *pNoname = KMemoryServiceHCD::Instance().GetStructs();    if( !pNoname )      return;    char szBufName[128] = {};    for( int i=0; i<_countof(params.szAddrs); ++i )    {      if( !params.szAddrs[i][0] )        break;      sprintf_s( szBufName, "%s:%s", params.szIP, params.szAddrs[i] );      int r = pNoname->CreateRefToData( szBufName, m_pRawBase, 0 );    }    for( int i=0; i<_countof(params.szNumbs); ++i )    {      if( !params.szNumbs[i][0] )        break;      //sprintf_s( szBufName, "%s:MATH_VAR%s", params.szIP, params.szNumbs[i] );      sprintf_s( szBufName, "%s:MATH_VAR%d", params.szIP, params.nPositions[i] );      int r = pNoname->CreateRefToData( szBufName, m_pRawBase, 0 );    }  }}